const std = @import("std");

const TreeNode = struct {
    value: i32,
    left: ?*TreeNode,
    right: ?*TreeNode,
};

fn inOrder(node: ?*TreeNode) void {
    if (node) |n| {
        inOrder(n.left);
        std.debug.print("{} ", .{n.value});
        inOrder(n.right);
    }
}

pub fn main() !void {
    var n3 = TreeNode{ .value = 3, .left = null, .right = null };
    var n4 = TreeNode{ .value = 4, .left = null, .right = null };
    var n2 = TreeNode{ .value = 2, .left = &n3, .right = &n4 };
    var n1 = TreeNode{ .value = 1, .left = null, .right = &n2 };

    inOrder(&n1);
    std.debug.print("\n", .{});
}

